pub const DERIVATIVE_ALGORITHM_VERSION: &str = "rust-vips-v1";
pub const DEFAULT_WORKERS: usize = 2;
pub const DEFAULT_QUEUE_CAPACITY: usize = 64;
pub const DEFAULT_WAITER_CAPACITY: usize = 64;
pub const MAXIMUM_OUTPUT_BYTES: u64 = 64 * 1024 * 1024;
const CACHE_RECORD_SCHEMA_VERSION: u32 = 2;
const MAXIMUM_METADATA_BYTES: u64 = 16 * 1024;
const CACHE_NAMESPACE: &str = "rust-vips-v1";
const NATIVE_WORK_CAPACITY: usize = 2;

type JobResult = Result<DerivativeResult, CacheError>;
pub type DerivativeProcess =
    dyn Fn(&[u8], DerivativeTarget) -> Result<Derivative, DerivativeError> + Send + Sync;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum DerivativeSource {
    MatchingJpeg,
    EmbeddedRawJpeg,
}

#[derive(Clone, Debug, PartialEq)]
pub struct DerivativeIdentity {
    pub photo_identity: String,
    pub source: DerivativeSource,
    pub source_relative_path: String,
    pub source_size: u64,
    pub source_mtime_ms: f64,
    pub embedded_candidate_identity: Option<String>,
    pub target: DerivativeTarget,
}

impl DerivativeIdentity {
    pub fn validate(&self) -> Result<(), CacheError> {
        if self.photo_identity.is_empty() || self.photo_identity.contains('\0') {
            return Err(CacheError::InvalidIdentity);
        }
        if self.source_relative_path.as_bytes().contains(&0)
            || !is_safe_relative_utf8_path(&self.source_relative_path)
        {
            return Err(CacheError::InvalidIdentity);
        }
        if !self.source_mtime_ms.is_finite() || self.source_mtime_ms < 0.0 {
            return Err(CacheError::InvalidIdentity);
        }
        if self.source == DerivativeSource::MatchingJpeg
            && self.embedded_candidate_identity.is_some()
        {
            return Err(CacheError::InvalidIdentity);
        }
        if let Some(candidate) = &self.embedded_candidate_identity
            && (candidate.is_empty() || candidate.contains('\0'))
        {
            return Err(CacheError::InvalidIdentity);
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum CacheError {
    Saturated,
    Closed,
    InvalidCacheDirectory,
    InvalidIdentity,
    UnsupportedEncoding,
    Io,
    InvalidCachedDerivative,
    Invalidated,
}

impl std::fmt::Display for CacheError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::Saturated => "Derivative scheduler is saturated",
            Self::Closed => "Derivative scheduler is closed",
            Self::InvalidCacheDirectory => "Derivative cache directory is invalid",
            Self::InvalidIdentity => "Derivative identity is invalid",
            Self::UnsupportedEncoding => "Derivative cache path encoding is unsupported",
            Self::Io => "Derivative cache I/O failed",
            Self::InvalidCachedDerivative => "Cached derivative failed validation",
            Self::Invalidated => "Derivative generation was invalidated",
        })
    }
}

impl std::error::Error for CacheError {}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
