#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CacheDirectory {
    root: Arc<CacheDirectoryInner>,
}

#[derive(Debug, Eq, PartialEq)]
struct CacheDirectoryInner {
    canonical_root: PathBuf,
    namespace_root: PathBuf,
    canonical_original_root: PathBuf,
}

impl CacheDirectory {
    /// Opens an owned cache directory and rejects a cache located below Originals.
    ///
    /// The canonical path is retained after this check. All generated names are fixed
    /// hexadecimal names or private temporary names, so identities never become paths.
    pub fn open(
        cache_directory: impl AsRef<Path>,
        original_root: impl AsRef<Path>,
    ) -> Result<Self, CacheError> {
        let cache_directory = cache_directory.as_ref();
        let original_root = original_root.as_ref();
        if !cache_directory.is_absolute() || !original_root.is_absolute() {
            return Err(CacheError::InvalidCacheDirectory);
        }
        if cache_directory.to_str().is_none() || original_root.to_str().is_none() {
            return Err(CacheError::UnsupportedEncoding);
        }
        let canonical_original_root =
            fs::canonicalize(original_root).map_err(|_| CacheError::InvalidCacheDirectory)?;
        if !canonical_original_root.is_dir() {
            return Err(CacheError::InvalidCacheDirectory);
        }
        reject_cache_under_original(cache_directory, &canonical_original_root)?;
        fs::create_dir_all(cache_directory).map_err(|_| CacheError::Io)?;
        let canonical_root = fs::canonicalize(cache_directory).map_err(|_| CacheError::Io)?;
        if !canonical_root.is_dir()
            || canonical_root == canonical_original_root
            || canonical_root.starts_with(&canonical_original_root)
        {
            return Err(CacheError::InvalidCacheDirectory);
        }
        if canonical_root.to_str().is_none() {
            return Err(CacheError::UnsupportedEncoding);
        }
        let namespace_path = canonical_root.join(CACHE_NAMESPACE);
        fs::create_dir_all(&namespace_path).map_err(|_| CacheError::Io)?;
        let namespace_root = fs::canonicalize(&namespace_path).map_err(|_| CacheError::Io)?;
        if !namespace_root.is_dir()
            || !namespace_root.starts_with(&canonical_root)
            || namespace_root.to_str().is_none()
        {
            return Err(CacheError::InvalidCacheDirectory);
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut permissions = fs::metadata(&canonical_root)
                .map_err(|_| CacheError::Io)?
                .permissions();
            permissions.set_mode(0o700);
            fs::set_permissions(&canonical_root, permissions).map_err(|_| CacheError::Io)?;
        }
        Ok(Self {
            root: Arc::new(CacheDirectoryInner {
                canonical_root,
                namespace_root,
                canonical_original_root,
            }),
        })
    }

    pub fn root(&self) -> &Path {
        &self.root.canonical_root
    }

    pub fn original_root(&self) -> &Path {
        &self.root.canonical_original_root
    }

    /// Looks up one current derivative from persisted cache metadata and the
    /// Library's published source facts. This path never opens an Original.
    /// Missing or invalid cache state is a miss so callers can use the normal
    /// bounded source-inspection path.
    pub fn lookup_current(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<CachedDerivative>, CacheError> {
        let Some(manifest) = self.current_manifest(photo, originals, target)? else {
            return Ok(None);
        };
        let Some(facts) = inspect_cached(&self.derivative_path(&manifest.key), target, &manifest)
        else {
            return Ok(None);
        };
        Ok(Some(cached_from_manifest(self, &manifest, facts, false)))
    }

    /// Returns the current manifest key after bounded metadata checks. This is
    /// only for Browse Window URL hydration; Preview requests and derivative
    /// delivery perform complete JPEG validation before serving bytes.
    pub fn lookup_current_key(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<String>, CacheError> {
        Ok(self
            .current_manifest(photo, originals, target)?
            .map(|manifest| manifest.key))
    }

    fn current_manifest(
        &self,
        photo: &PhotoRecord,
        originals: &[OriginalRecord],
        target: DerivativeTarget,
    ) -> Result<Option<Manifest>, CacheError> {
        let path = self.manifest_path_for_photo_target(&photo.id, target)?;
        let Ok(manifest) = read_manifest(&path) else {
            return Ok(None);
        };
        let find = |id: &Option<String>, kind: OriginalKind| {
            id.as_ref().and_then(|id| {
                originals.iter().find(|original| {
                    &original.id == id
                        && original.kind == kind
                        && original.available
                        && original.error_category.is_none()
                })
            })
        };
        let selected = selected_original(photo, originals);
        let persisted = photo.preview_source.and_then(|source| match source {
            PreviewCandidate::MatchingJpeg => find(&photo.jpeg_original_id, OriginalKind::Jpeg)
                .map(|original| (PreviewCandidate::MatchingJpeg, original)),
            PreviewCandidate::EmbeddedRawJpeg => find(&photo.raw_original_id, OriginalKind::Raw)
                .map(|original| (PreviewCandidate::EmbeddedRawJpeg, original)),
        });
        let Some((candidate, original)) = persisted.or(selected) else {
            return Ok(None);
        };

        let manifest_source = match candidate {
            PreviewCandidate::MatchingJpeg => DerivativeSource::MatchingJpeg,
            PreviewCandidate::EmbeddedRawJpeg => DerivativeSource::EmbeddedRawJpeg,
        };
        if !manifest_key_is_valid(&manifest)
            || manifest.photo_identity != photo.id
            || manifest.target_long_edge != target.long_edge()
            || manifest.source != manifest_source
            || manifest.source_relative_path != original.relative_path.as_str()
            || manifest.source_size != original.facts.size
            || manifest.source_mtime_ms != original.facts.mtime_ms
            || (candidate == PreviewCandidate::MatchingJpeg
                && manifest.embedded_candidate_identity.is_some())
            || photo.preview_source.is_some_and(|source| {
                source != candidate
                    || photo.preview_source_revision.as_deref()
                        != source_revision(
                            original.relative_path.as_str(),
                            original.facts.size,
                            original.facts.mtime_ms,
                        )
                        .ok()
                        .as_deref()
            })
        {
            return Ok(None);
        }
        let metadata = fs::symlink_metadata(self.derivative_path(&manifest.key)).ok();
        if !metadata.is_some_and(|metadata| {
            metadata.is_file() && metadata.len() > 0 && metadata.len() <= MAXIMUM_OUTPUT_BYTES
        }) {
            return Ok(None);
        }
        Ok(Some(manifest))
    }

    fn manifest_path_for_photo_target(
        &self,
        photo_id: &str,
        target: DerivativeTarget,
    ) -> Result<PathBuf, CacheError> {
        let identity = manifest_identity_for_photo_target(photo_id, target)?;
        Ok(self
            .root
            .namespace_root
            .join("metadata")
            .join("manifests")
            .join(format!("{identity}.json")))
    }

    /// Reads one already-published derivative by its cache identity.
    ///
    /// Callers provide only the validated hexadecimal identity; cache path
    /// construction and no-follow file admission remain inside the cache
    /// boundary. This keeps filesystem paths out of the HTTP and Preview APIs.
    pub fn read_derivative(
        &self,
        key: &str,
        target: DerivativeTarget,
    ) -> Result<Vec<u8>, CacheError> {
        if !is_hex_key(key) {
            return Err(CacheError::InvalidIdentity);
        }
        let path = self.derivative_path(key);
        let file = OpenOptions::new()
            .read(true)
            .custom_flags(no_follow_flag())
            .open(path)
            .map_err(|_| CacheError::Io)?;
        let metadata = file.metadata().map_err(|_| CacheError::Io)?;
        if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAXIMUM_OUTPUT_BYTES {
            return Err(CacheError::InvalidCachedDerivative);
        }
        let mut bytes = Vec::with_capacity(metadata.len() as usize);
        file.take(MAXIMUM_OUTPUT_BYTES + 1)
            .read_to_end(&mut bytes)
            .map_err(|_| CacheError::Io)?;
        if bytes.len() as u64 > MAXIMUM_OUTPUT_BYTES {
            return Err(CacheError::InvalidCachedDerivative);
        }
        let Some(facts) = jpeg_facts(&bytes) else {
            return Err(CacheError::InvalidCachedDerivative);
        };
        if facts.width.max(facts.height) > target.long_edge()
            || validate_jpeg_bytes(&bytes, facts, false).is_none()
        {
            return Err(CacheError::InvalidCachedDerivative);
        }
        Ok(bytes)
    }

    fn derivative_path(&self, key: &str) -> PathBuf {
        self.root.namespace_root.join(format!("{key}.jpg"))
    }

    fn manifest_path(&self, identity: &DerivativeIdentity) -> Result<PathBuf, CacheError> {
        self.manifest_path_for_photo_target(&identity.photo_identity, identity.target)
    }

    fn failure_path(&self, key: &str) -> PathBuf {
        self.root
            .namespace_root
            .join("metadata")
            .join("failures")
            .join(format!("{key}.json"))
    }

    fn ensure_metadata(&self) -> Result<(), CacheError> {
        fs::create_dir_all(self.root.namespace_root.join("metadata/manifests"))
            .map_err(|_| CacheError::Io)?;
        fs::create_dir_all(self.root.namespace_root.join("metadata/failures"))
            .map_err(|_| CacheError::Io)?;
        Ok(())
    }
}

