#[derive(Clone)]
struct JobCell {
    value: Arc<(Mutex<Option<JobResult>>, Condvar)>,
}

impl JobCell {
    fn new() -> Self {
        Self {
            value: Arc::new((Mutex::new(None), Condvar::new())),
        }
    }

    fn complete(&self, result: Result<DerivativeResult, CacheError>) {
        let (lock, signal) = &*self.value;
        let mut value = lock.lock().expect("job cell poisoned");
        if value.is_none() {
            *value = Some(result);
            signal.notify_all();
        }
    }

    fn wait(&self) -> Result<DerivativeResult, CacheError> {
        let (lock, signal) = &*self.value;
        let mut result = lock.lock().expect("job cell poisoned");
        while result.is_none() {
            result = signal.wait(result).expect("job cell poisoned");
        }
        result
            .as_ref()
            .expect("job cell result disappeared")
            .clone()
    }
}

