/// Shared bounded admission for native parsing, LibRaw, and libvips work.
/// A Library creates one budget; standalone schedulers create their own.
#[derive(Clone)]
pub struct NativeWorkBudget(Arc<NativeWorkSemaphore>);

struct NativeWorkSemaphore {
    state: Mutex<NativeWorkState>,
    signal: Condvar,
    active: AtomicU64,
    peak: AtomicU64,
}

struct NativeWorkState {
    available: usize,
}

pub(crate) struct NativeWorkPermit {
    semaphore: Arc<NativeWorkSemaphore>,
}

impl NativeWorkBudget {
    pub fn new() -> Self {
        Self(NativeWorkSemaphore::new(NATIVE_WORK_CAPACITY))
    }

    pub(crate) fn acquire(&self) -> NativeWorkPermit {
        self.0.acquire()
    }

    #[cfg(test)]
    pub(crate) fn peak(&self) -> u64 {
        self.0.peak.load(Ordering::Acquire)
    }
}

impl Default for NativeWorkBudget {
    fn default() -> Self {
        Self::new()
    }
}

impl NativeWorkSemaphore {
    fn new(capacity: usize) -> Arc<Self> {
        Arc::new(Self {
            state: Mutex::new(NativeWorkState {
                available: capacity,
            }),
            signal: Condvar::new(),
            active: AtomicU64::new(0),
            peak: AtomicU64::new(0),
        })
    }

    fn acquire(self: &Arc<Self>) -> NativeWorkPermit {
        let mut state = self.state.lock().expect("native work semaphore poisoned");
        while state.available == 0 {
            state = self
                .signal
                .wait(state)
                .expect("native work semaphore poisoned");
        }
        state.available -= 1;
        drop(state);

        let active = self.active.fetch_add(1, Ordering::AcqRel) + 1;
        self.peak.fetch_max(active, Ordering::Relaxed);
        NativeWorkPermit {
            semaphore: Arc::clone(self),
        }
    }
}

impl Drop for NativeWorkPermit {
    fn drop(&mut self) {
        self.semaphore.active.fetch_sub(1, Ordering::AcqRel);
        let mut state = self
            .semaphore
            .state
            .lock()
            .expect("native work semaphore poisoned");
        state.available += 1;
        drop(state);
        self.semaphore.signal.notify_one();
    }
}

struct SchedulerInner {
    cache: CacheDirectory,
    native_work: NativeWorkBudget,
    state: Mutex<SchedulerState>,
    signal: Condvar,
    workers: Mutex<Vec<JoinHandle<()>>>,
    worker_count: usize,
    queue_capacity: usize,
    waiter_capacity: usize,
    process: Arc<DerivativeProcess>,
}

static SCHEDULERS: OnceLock<Mutex<HashMap<PathBuf, Weak<SchedulerInner>>>> = OnceLock::new();
static NEXT_TEMPORARY: AtomicU64 = AtomicU64::new(0);

#[derive(Clone)]
pub struct DerivativeScheduler {
    inner: Arc<SchedulerInner>,
}

#[derive(Clone)]
pub struct DerivativeSchedulerOptions {
    pub workers: usize,
    pub queue_capacity: usize,
    pub waiter_capacity: usize,
    pub process: Option<Arc<DerivativeProcess>>,
}

impl Default for DerivativeSchedulerOptions {
    fn default() -> Self {
        Self {
            workers: DEFAULT_WORKERS,
            queue_capacity: DEFAULT_QUEUE_CAPACITY,
            waiter_capacity: DEFAULT_WAITER_CAPACITY,
            process: None,
        }
    }
}

impl DerivativeScheduler {
    pub fn new(cache: CacheDirectory) -> Result<Self, CacheError> {
        Self::with_options(cache, DerivativeSchedulerOptions::default())
    }

    pub fn with_options(
        cache: CacheDirectory,
        options: DerivativeSchedulerOptions,
    ) -> Result<Self, CacheError> {
        Self::with_native_work_budget(cache, options, NativeWorkBudget::new())
    }

    pub(crate) fn with_native_work_budget(
        cache: CacheDirectory,
        options: DerivativeSchedulerOptions,
        native_work: NativeWorkBudget,
    ) -> Result<Self, CacheError> {
        if options.workers == 0 || options.queue_capacity == 0 || options.waiter_capacity == 0 {
            return Err(CacheError::InvalidCacheDirectory);
        }
        cache.ensure_metadata()?;
        let registry = SCHEDULERS.get_or_init(|| Mutex::new(HashMap::new()));
        let mut entries = registry.lock().expect("scheduler registry poisoned");
        if let Some(existing) = entries.get(cache.root()).and_then(Weak::upgrade) {
            if existing.worker_count != options.workers
                || existing.queue_capacity != options.queue_capacity
                || existing.waiter_capacity != options.waiter_capacity
            {
                return Err(CacheError::InvalidCacheDirectory);
            }
            return Ok(Self { inner: existing });
        }
        let cache_root = cache.root().to_owned();
        let inner = Arc::new(SchedulerInner {
            cache,
            native_work,
            state: Mutex::new(SchedulerState {
                closed: false,
                terminate_workers: false,
                active: 0,
                next_order: 0,
                next_generation: 0,
                waiter_count: 0,
                queue: VecDeque::new(),
                in_flight: HashMap::new(),
                authoritative: HashMap::new(),
                invalidating: HashSet::new(),
                failed: HashMap::new(),
            }),
            signal: Condvar::new(),
            workers: Mutex::new(Vec::new()),
            worker_count: options.workers,
            queue_capacity: options.queue_capacity,
            waiter_capacity: options.waiter_capacity,
            process: options.process.unwrap_or_else(|| Arc::new(process_jpeg)),
        });
        let mut workers = inner.workers.lock().expect("worker list poisoned");
        for index in 0..inner.worker_count {
            let worker = Arc::clone(&inner);
            workers.push(
                thread::Builder::new()
                    .name(format!("slipstream-derivative-{index}"))
                    .spawn(move || worker_loop(worker))
                    .map_err(|_| CacheError::Io)?,
            );
        }
        drop(workers);
        entries.insert(cache_root, Arc::downgrade(&inner));
        Ok(Self { inner })
    }

    pub fn cache(&self) -> &CacheDirectory {
        &self.inner.cache
    }

    pub(crate) fn acquire_native_work(&self) -> NativeWorkPermit {
        self.inner.native_work.acquire()
    }

    pub fn generate(
        &self,
        identity: DerivativeIdentity,
        jpeg: Vec<u8>,
        priority: DerivativePriority,
    ) -> Result<DerivativeResult, CacheError> {
        identity.validate()?;
        let key = derivative_cache_key(&identity)?;
        let manifest_key = manifest_identity(&identity)?;
        let mut detached = Vec::new();
        let cell;
        {
            let mut state = self.inner.state.lock().expect("scheduler state poisoned");
            if state.closed {
                return Err(CacheError::Closed);
            }
            while state.invalidating.contains(&key) {
                state = self
                    .inner
                    .signal
                    .wait(state)
                    .expect("scheduler state poisoned");
                if state.closed {
                    return Err(CacheError::Closed);
                }
            }
            if let Some(failure) = state.failed.get(&key).cloned() {
                state.waiter_count += 1;
                drop(state);
                let result = stale_or_failure(
                    &self.inner,
                    &identity,
                    failure_record(&identity, &key, failure.kind),
                );
                let mut state = self.inner.state.lock().expect("scheduler state poisoned");
                state.waiter_count = state.waiter_count.saturating_sub(1);
                return result;
            }
            if state.waiter_count >= self.inner.waiter_capacity {
                return Err(CacheError::Saturated);
            }
            if let Some(existing) = state.in_flight.get(&key) {
                let existing_meta = Arc::clone(&existing.meta);
                let existing_cell = existing.cell.clone();
                let mut existing_priority = existing_meta
                    .priority
                    .lock()
                    .expect("job metadata poisoned");
                if priority < *existing_priority {
                    *existing_priority = priority;
                }
                cell = existing_cell;
            } else {
                if state.queue.len() >= self.inner.queue_capacity {
                    return Err(CacheError::Saturated);
                }
                state.next_order = state
                    .next_order
                    .checked_add(1)
                    .ok_or(CacheError::Saturated)?;
                state.next_generation = state
                    .next_generation
                    .checked_add(1)
                    .ok_or(CacheError::Saturated)?;
                let meta = Arc::new(JobMeta {
                    priority: Mutex::new(priority),
                    order: state.next_order,
                });
                cell = JobCell::new();
                let generation = state.next_generation;
                let manifest_in_flight = state
                    .in_flight
                    .values()
                    .any(|existing| existing.manifest_key == manifest_key);
                if manifest_in_flight {
                    state.authoritative.insert(manifest_key.clone(), generation);
                    let mut detached_keys = Vec::new();
                    state.queue.retain(|job| {
                        if job.manifest_key == manifest_key && job.key != key {
                            detached.push(job.cell.clone());
                            detached_keys.push(job.key.clone());
                            false
                        } else {
                            true
                        }
                    });
                    for detached_key in detached_keys {
                        state.in_flight.remove(&detached_key);
                    }
                } else {
                    state.authoritative.insert(manifest_key.clone(), generation);
                }
                state.in_flight.insert(
                    key.clone(),
                    InFlight {
                        cell: cell.clone(),
                        meta: Arc::clone(&meta),
                        manifest_key: manifest_key.clone(),
                        generation,
                    },
                );
                state.queue.push_back(QueuedJob {
                    identity,
                    jpeg,
                    key,
                    manifest_key,
                    generation,
                    meta,
                    cell: cell.clone(),
                });
                self.inner.signal.notify_one();
            }
            state.waiter_count += 1;
        }
        for cell in detached {
            cell.complete(Err(CacheError::Invalidated));
        }
        let result = cell.wait();
        let mut state = self.inner.state.lock().expect("scheduler state poisoned");
        state.waiter_count = state.waiter_count.saturating_sub(1);
        drop(state);
        result
    }

    pub fn retry(
        &self,
        identity: DerivativeIdentity,
        jpeg: Vec<u8>,
        priority: DerivativePriority,
    ) -> Result<DerivativeResult, CacheError> {
        self.invalidate(&identity)?;
        self.generate(identity, jpeg, priority)
    }

    /// Removes the current identity's terminal failure and derivative bytes.
    pub fn invalidate(&self, identity: &DerivativeIdentity) -> Result<(), CacheError> {
        identity.validate()?;
        let key = derivative_cache_key(identity)?;
        let manifest_key = manifest_identity(identity)?;
        let mut state = self.inner.state.lock().expect("scheduler state poisoned");
        state.next_generation = state
            .next_generation
            .checked_add(1)
            .ok_or(CacheError::Saturated)?;
        let generation = state.next_generation;
        state.authoritative.insert(manifest_key, generation);
        state.invalidating.insert(key.clone());
        state.failed.remove(&key);
        // Detach queued work immediately. Active work is also detached from
        // `in_flight`, allowing a same-key retry to enqueue a fresh generation;
        // the worker completion path only removes its own generation below.
        let mut detached = Vec::new();
        state.queue.retain(|job| {
            if job.key == key {
                detached.push(job.cell.clone());
                false
            } else {
                true
            }
        });
        if let Some(existing) = state.in_flight.get(&key)
            && existing.generation != generation
        {
            detached.push(existing.cell.clone());
            state.in_flight.remove(&key);
        }
        drop(state);
        for cell in detached {
            cell.complete(Err(CacheError::Invalidated));
        }
        let result = (|| {
            remove_if_present(&self.inner.cache.derivative_path(&key))?;
            remove_if_present(&self.inner.cache.failure_path(&key))?;
            let manifest_path = self.inner.cache.manifest_path(identity)?;
            if let Ok(manifest) = read_manifest(&manifest_path)
                && manifest_matches_identity(&manifest, identity)
                && manifest.key == key
            {
                remove_if_present(&manifest_path)?;
            }
            Ok(())
        })();
        let mut state = self.inner.state.lock().expect("scheduler state poisoned");
        state.invalidating.remove(&key);
        self.inner.signal.notify_all();
        result
    }

    /// Stops admission, drains accepted jobs, and waits for every worker to exit.
    pub fn shutdown(&self) -> Result<(), CacheError> {
        let workers = {
            let mut state = self.inner.state.lock().expect("scheduler state poisoned");
            if !state.closed {
                state.closed = true;
                self.inner.signal.notify_all();
            }
            while !(state.queue.is_empty() && state.active == 0 && state.in_flight.is_empty()) {
                state = self
                    .inner
                    .signal
                    .wait(state)
                    .expect("scheduler state poisoned");
            }
            state.terminate_workers = true;
            self.inner.signal.notify_all();
            self.inner
                .workers
                .lock()
                .expect("worker list poisoned")
                .drain(..)
                .collect::<Vec<_>>()
        };
        for worker in workers {
            worker.join().map_err(|_| CacheError::Io)?;
        }
        let registry = SCHEDULERS.get_or_init(|| Mutex::new(HashMap::new()));
        registry
            .lock()
            .expect("scheduler registry poisoned")
            .retain(|_, weak| {
                weak.upgrade()
                    .is_some_and(|inner| !Arc::ptr_eq(&inner, &self.inner))
            });
        Ok(())
    }
}

fn worker_loop(inner: Arc<SchedulerInner>) {
    loop {
        let job = {
            let mut state = inner.state.lock().expect("scheduler state poisoned");
            loop {
                if state.terminate_workers {
                    return;
                }
                if !state.queue.is_empty() {
                    let selected = state
                        .queue
                        .iter()
                        .enumerate()
                        .min_by_key(|(_, job)| {
                            (
                                job.meta
                                    .priority
                                    .lock()
                                    .expect("job metadata poisoned")
                                    .rank(),
                                job.meta.order,
                            )
                        })
                        .map(|(index, _)| index)
                        .expect("nonempty queue");
                    state.active += 1;
                    break state.queue.remove(selected).expect("selected queue job");
                }
                if state.closed && state.active == 0 {
                    state.terminate_workers = true;
                    inner.signal.notify_all();
                    return;
                }
                state = inner.signal.wait(state).expect("scheduler state poisoned");
            }
        };
        let result = generate_one(&inner, &job);
        let mut state = inner.state.lock().expect("scheduler state poisoned");
        state.active = state.active.saturating_sub(1);
        if state
            .in_flight
            .get(&job.key)
            .is_some_and(|in_flight| in_flight.generation == job.generation)
        {
            state.in_flight.remove(&job.key);
        }
        // All result paths, including cache hits and failures, must honor takeover
        // before a waiter can observe their result.
        let result = if state.authoritative.get(&job.manifest_key).copied() == Some(job.generation)
        {
            result
        } else {
            Err(CacheError::Invalidated)
        };
        job.cell.complete(result);
        if state.closed && state.queue.is_empty() && state.active == 0 && state.in_flight.is_empty()
        {
            inner.signal.notify_all();
        } else {
            inner.signal.notify_one();
        }
    }
}

fn job_is_authoritative(inner: &SchedulerInner, job: &QueuedJob) -> bool {
    let state = inner.state.lock().expect("scheduler state poisoned");
    state.authoritative.get(&job.manifest_key).copied() == Some(job.generation)
}

fn authoritative_result(
    inner: &SchedulerInner,
    job: &QueuedJob,
    result: Result<DerivativeResult, CacheError>,
) -> Result<DerivativeResult, CacheError> {
    if job_is_authoritative(inner, job) {
        result
    } else {
        Err(CacheError::Invalidated)
    }
}

fn generate_one(inner: &SchedulerInner, job: &QueuedJob) -> Result<DerivativeResult, CacheError> {
    let final_path = inner.cache.derivative_path(&job.key);
    if let Some(failure) =
        read_failure(&inner.cache.failure_path(&job.key), &job.identity, &job.key)
    {
        let mut state = inner.state.lock().expect("scheduler state poisoned");
        if state.authoritative.get(&job.manifest_key).copied() != Some(job.generation) {
            return Err(CacheError::Invalidated);
        }
        state.failed.insert(
            job.key.clone(),
            DerivativeFailure {
                kind: match failure.kind {
                    PersistentFailureKind::Unsupported => DerivativeFailureKind::Unsupported,
                    PersistentFailureKind::Malformed => DerivativeFailureKind::Malformed,
                    PersistentFailureKind::ResourceLimit => DerivativeFailureKind::ResourceLimit,
                },
            },
        );
        drop(state);
        return authoritative_result(inner, job, stale_or_failure(inner, &job.identity, failure));
    }
    if let Ok(manifest) = read_manifest(&inner.cache.manifest_path(&job.identity)?)
        && manifest_matches_identity(&manifest, &job.identity)
        && manifest.key == job.key
        && let Some(facts) = inspect_cached(&final_path, job.identity.target, &manifest)
    {
        return authoritative_result(
            inner,
            job,
            Ok(DerivativeResult::Ready(cached_from_manifest(
                &inner.cache,
                &manifest,
                facts,
                false,
            ))),
        );
    }
    let prior = read_manifest(&inner.cache.manifest_path(&job.identity)?)
        .ok()
        .filter(|manifest| manifest_is_for_photo_target(manifest, &job.identity));
    let process_result = {
        let _permit = inner.native_work.acquire();
        (inner.process)(&job.jpeg, job.identity.target)
    };
    let processed = match process_result {
        Ok(processed) => match validate_processed(&processed, job.identity.target) {
            Ok(()) => processed,
            Err(error) => return persist_or_stale(inner, job, prior, error),
        },
        Err(error) => return persist_or_stale(inner, job, prior, error),
    };

    // Holding the state lock makes cache shutdown and invalidation the publication
    // linearization points: either one winning first suppresses all old output.
    let state = inner.state.lock().expect("scheduler state poisoned");
    if state.closed {
        drop(state);
        return Err(CacheError::Closed);
    }
    if state.authoritative.get(&job.manifest_key).copied() != Some(job.generation) {
        drop(state);
        return Err(CacheError::Invalidated);
    }
    let published = match publish_derivative(&inner.cache, &final_path, &processed) {
        Ok(()) => true,
        Err(_) => {
            drop(state);
            return persist_or_stale(inner, job, prior, DerivativeError::Internal);
        }
    };
    let current = Manifest {
        schema_version: CACHE_RECORD_SCHEMA_VERSION,
        algorithm_version: DERIVATIVE_ALGORITHM_VERSION.to_owned(),
        photo_identity: job.identity.photo_identity.clone(),
        target_long_edge: job.identity.target.long_edge(),
        key: job.key.clone(),
        source: job.identity.source,
        width: processed.width,
        height: processed.height,
        color_profile: processed.profile.into(),
        source_relative_path: job.identity.source_relative_path.clone(),
        source_size: job.identity.source_size,
        source_mtime_ms: job.identity.source_mtime_ms,
        source_mtime_bits: job.identity.source_mtime_ms.to_bits(),
        embedded_candidate_identity: job.identity.embedded_candidate_identity.clone(),
    };
    let current_generation = state.authoritative.get(&job.manifest_key).copied();
    let manifest_published = current_generation == Some(job.generation)
        && publish_manifest(&inner.cache, &job.identity, &current).is_ok();
    drop(state);
    if published && manifest_published {
        Ok(DerivativeResult::Ready(cached_from_manifest(
            &inner.cache,
            &current,
            ManifestFacts {
                width: processed.width,
                height: processed.height,
            },
            true,
        )))
    } else if published {
        // Bytes without an authoritative manifest are never reported current.
        // Only a manifest that was already durable before this attempt can be
        // returned as stale; the just-built bytes have no trusted identity.
        persist_or_stale(inner, job, prior, DerivativeError::Internal)
    } else {
        Err(CacheError::Io)
    }
}

fn persist_or_stale(
    inner: &SchedulerInner,
    job: &QueuedJob,
    prior: Option<Manifest>,
    error: DerivativeError,
) -> Result<DerivativeResult, CacheError> {
    let classified = failure_for_error(error);
    let mut state = inner.state.lock().expect("scheduler state poisoned");
    if state.authoritative.get(&job.manifest_key).copied() != Some(job.generation) {
        return Err(CacheError::Invalidated);
    }
    if matches!(
        classified.kind,
        DerivativeFailureKind::Unsupported
            | DerivativeFailureKind::Malformed
            | DerivativeFailureKind::ResourceLimit
    ) {
        let _ = persist_failure(
            &inner.cache.failure_path(&job.key),
            failure_record(&job.identity, &job.key, classified.kind),
        );
        state.failed.insert(job.key.clone(), classified.clone());
    }
    drop(state);
    let result = if let Some(manifest) = prior
        && let Some(facts) = inspect_cached(
            &inner.cache.derivative_path(&manifest.key),
            job.identity.target,
            &manifest,
        ) {
        Ok(DerivativeResult::Ready(CachedDerivative {
            cache_path: inner.cache.derivative_path(&manifest.key),
            cache_key: manifest.key,
            source: manifest.source,
            source_relative_path: manifest.source_relative_path.clone(),
            source_size: manifest.source_size,
            source_mtime_ms: manifest.source_mtime_ms,
            embedded_candidate_identity: manifest.embedded_candidate_identity.clone(),
            width: facts.width,
            height: facts.height,
            profile: manifest.color_profile.into(),
            generated: false,
            stale: true,
        }))
    } else {
        Ok(DerivativeResult::Failed(DerivativeFailure {
            kind: classified.kind,
        }))
    };
    authoritative_result(inner, job, result)
}

fn stale_or_failure(
    inner: &SchedulerInner,
    identity: &DerivativeIdentity,
    failure: FailureRecord,
) -> Result<DerivativeResult, CacheError> {
    if let Ok(manifest) = read_manifest(&inner.cache.manifest_path(identity)?)
        && manifest_is_stale_for_identity(&manifest, identity)
        && let Some(facts) = inspect_cached(
            &inner.cache.derivative_path(&manifest.key),
            identity.target,
            &manifest,
        )
    {
        return Ok(DerivativeResult::Ready(CachedDerivative {
            cache_path: inner.cache.derivative_path(&manifest.key),
            cache_key: manifest.key,
            source: manifest.source,
            source_relative_path: manifest.source_relative_path.clone(),
            source_size: manifest.source_size,
            source_mtime_ms: manifest.source_mtime_ms,
            embedded_candidate_identity: manifest.embedded_candidate_identity.clone(),
            width: facts.width,
            height: facts.height,
            profile: manifest.color_profile.into(),
            generated: false,
            stale: true,
        }));
    }
    Ok(DerivativeResult::Failed(DerivativeFailure {
        kind: match failure.kind {
            PersistentFailureKind::Unsupported => DerivativeFailureKind::Unsupported,
            PersistentFailureKind::Malformed => DerivativeFailureKind::Malformed,
            PersistentFailureKind::ResourceLimit => DerivativeFailureKind::ResourceLimit,
        },
    }))
}

fn publish_derivative(
    cache: &CacheDirectory,
    final_path: &Path,
    processed: &Derivative,
) -> Result<(), CacheError> {
    let temporary = cache.root().join(format!(
        ".{}.{}.{}.tmp",
        final_path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or(CacheError::UnsupportedEncoding)?,
        std::process::id(),
        NEXT_TEMPORARY.fetch_add(1, Ordering::Relaxed)
    ));
    write_new_file(&temporary, &processed.jpeg)?;
    match fs::rename(&temporary, final_path) {
        Ok(()) => Ok(()),
        Err(_) => {
            let _ = fs::remove_file(&temporary);
            Err(CacheError::Io)
        }
    }
}

fn publish_manifest(
    cache: &CacheDirectory,
    identity: &DerivativeIdentity,
    manifest: &Manifest,
) -> Result<(), CacheError> {
    let path = cache.manifest_path(identity)?;
    let bytes = serde_json::to_vec(manifest).map_err(|_| CacheError::Io)?;
    let temporary = path.with_extension(format!(
        "json.{}.{}.tmp",
        std::process::id(),
        NEXT_TEMPORARY.fetch_add(1, Ordering::Relaxed)
    ));
    write_new_file(&temporary, &bytes)?;
    match fs::rename(&temporary, &path) {
        Ok(()) => Ok(()),
        Err(_) => {
            let _ = fs::remove_file(&temporary);
            Err(CacheError::Io)
        }
    }
}

fn write_new_file(path: &Path, bytes: &[u8]) -> Result<(), CacheError> {
    let result = (|| {
        let mut file = OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(path)
            .map_err(|_| CacheError::Io)?;
        file.write_all(bytes).map_err(|_| CacheError::Io)?;
        file.sync_all().map_err(|_| CacheError::Io)?;
        Ok::<(), CacheError>(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(path);
    }
    result
}

fn inspect_cached(
    path: &Path,
    target: DerivativeTarget,
    manifest: &Manifest,
) -> Option<ManifestFacts> {
    let metadata = fs::symlink_metadata(path).ok()?;
    if !metadata.is_file() || metadata.len() == 0 || metadata.len() > MAXIMUM_OUTPUT_BYTES {
        return None;
    }
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(no_follow_flag())
        .open(path)
        .ok()?;
    let mut bytes = Vec::with_capacity(metadata.len() as usize);
    file.take(MAXIMUM_OUTPUT_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > MAXIMUM_OUTPUT_BYTES {
        return None;
    }
    let facts = jpeg_facts(&bytes)?;
    if facts.width != manifest.width
        || facts.height != manifest.height
        || facts.width.max(facts.height) > target.long_edge()
    {
        return None;
    }
    validate_cached_jpeg(&bytes, facts, manifest.color_profile)?;
    Some(facts)
}

fn validate_processed(
    processed: &Derivative,
    target: DerivativeTarget,
) -> Result<(), DerivativeError> {
    if processed.jpeg.is_empty() || processed.jpeg.len() as u64 > MAXIMUM_OUTPUT_BYTES {
        return Err(DerivativeError::OutputLimit);
    }
    if processed.width == 0
        || processed.height == 0
        || processed.width.max(processed.height) > target.long_edge()
    {
        return Err(DerivativeError::Internal);
    }
    let facts = jpeg_facts(&processed.jpeg).ok_or(DerivativeError::Malformed)?;
    if facts.width != processed.width || facts.height != processed.height {
        return Err(DerivativeError::Internal);
    }
    if processed.profile == DerivativeProfile::PreservedIcc && !contains_icc(&processed.jpeg) {
        return Err(DerivativeError::Internal);
    }
    Ok(())
}

fn jpeg_facts(bytes: &[u8]) -> Option<ManifestFacts> {
    if bytes.len() < 4 || bytes[0] != 0xff || bytes[1] != 0xd8 {
        return None;
    }
    let mut offset = 2usize;
    let mut dimensions = None;
    let mut saw_scan = false;
    let mut saw_eoi = false;
    while offset + 1 < bytes.len() {
        while offset < bytes.len() && bytes[offset] == 0xff {
            offset += 1;
        }
        if offset >= bytes.len() {
            break;
        }
        let marker = bytes[offset];
        offset += 1;
        if marker == 0xd9 {
            saw_eoi = true;
            break;
        }
        if marker == 0xda {
            saw_scan = true;
            break;
        }
        if marker == 0x00 || (0xd0..=0xd7).contains(&marker) {
            continue;
        }
        if offset + 2 > bytes.len() {
            return None;
        }
        let length = u16::from_be_bytes([bytes[offset], bytes[offset + 1]]) as usize;
        if length < 2 || offset + length > bytes.len() {
            return None;
        }
        if is_jpeg_frame_marker(marker) {
            if length < 7 {
                return None;
            }
            let height = u16::from_be_bytes([bytes[offset + 3], bytes[offset + 4]]) as u32;
            let width = u16::from_be_bytes([bytes[offset + 5], bytes[offset + 6]]) as u32;
            if width == 0 || height == 0 {
                return None;
            }
            dimensions = Some(ManifestFacts { width, height });
        }
        offset += length;
    }
    if saw_scan {
        let mut index = offset;
        while index + 1 < bytes.len() {
            if bytes[index] == 0xff && bytes[index + 1] == 0xd9 {
                saw_eoi = true;
                break;
            }
            index += 1;
        }
    }
    if !saw_eoi && bytes.ends_with(&[0xff, 0xd9]) {
        saw_eoi = true;
    }
    dimensions.filter(|_| saw_eoi)
}

const fn is_jpeg_frame_marker(marker: u8) -> bool {
    matches!(marker, 0xc0..=0xc3 | 0xc5..=0xc7 | 0xc9..=0xcb | 0xcd..=0xcf)
}

fn validate_cached_jpeg(
    bytes: &[u8],
    facts: ManifestFacts,
    profile: DerivativeProfileWire,
) -> Option<()> {
    validate_jpeg_bytes(bytes, facts, profile == DerivativeProfileWire::PreservedIcc)
}

fn validate_jpeg_bytes(bytes: &[u8], facts: ManifestFacts, require_icc: bool) -> Option<()> {
    let mut decoder = JpegDecoder::new(Cursor::new(bytes)).ok()?;
    if decoder.dimensions() != (facts.width, facts.height) {
        return None;
    }
    let icc = decoder.icc_profile().ok().flatten();
    if require_icc && icc.is_none() {
        return None;
    }
    if let Some(icc) = icc {
        Profile::new_icc(&icc).ok()?;
    }
    let decoded_bytes = usize::try_from(decoder.total_bytes()).ok()?;
    let mut decoded = vec![0; decoded_bytes];
    decoder.read_image(&mut decoded).ok()?;
    Some(())
}

fn contains_icc(bytes: &[u8]) -> bool {
    bytes.windows(12).any(|window| window == b"ICC_PROFILE\0")
}

fn read_manifest(path: &Path) -> Result<Manifest, CacheError> {
    let mut bytes = Vec::new();
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(no_follow_flag())
        .open(path)
        .map_err(|_| CacheError::Io)?;
    let metadata = file.metadata().map_err(|_| CacheError::Io)?;
    if !metadata.is_file() || metadata.len() > MAXIMUM_METADATA_BYTES {
        return Err(CacheError::InvalidCachedDerivative);
    }
    file.take(MAXIMUM_METADATA_BYTES + 1)
        .read_to_end(&mut bytes)
        .map_err(|_| CacheError::Io)?;
    if bytes.len() as u64 > MAXIMUM_METADATA_BYTES {
        return Err(CacheError::InvalidCachedDerivative);
    }
    let mut manifest: Manifest =
        serde_json::from_slice(&bytes).map_err(|_| CacheError::InvalidCachedDerivative)?;
    let exact_mtime_ms = f64::from_bits(manifest.source_mtime_bits);
    if !exact_mtime_ms.is_finite() || exact_mtime_ms < 0.0 {
        return Err(CacheError::InvalidCachedDerivative);
    }
    manifest.source_mtime_ms = exact_mtime_ms;
    if manifest.schema_version != CACHE_RECORD_SCHEMA_VERSION
        || manifest.algorithm_version != DERIVATIVE_ALGORITHM_VERSION
        || manifest.width == 0
        || manifest.height == 0
        || !matches!(manifest.target_long_edge, 512 | 2560)
        || !is_hex_key(&manifest.key)
    {
        return Err(CacheError::InvalidCachedDerivative);
    }
    Ok(manifest)
}

fn read_failure(
    path: &Path,
    identity: &DerivativeIdentity,
    expected_key: &str,
) -> Option<FailureRecord> {
    let mut bytes = Vec::new();
    let file = OpenOptions::new()
        .read(true)
        .custom_flags(no_follow_flag())
        .open(path)
        .ok()?;
    let metadata = file.metadata().ok()?;
    if !metadata.is_file() || metadata.len() > MAXIMUM_METADATA_BYTES {
        return None;
    }
    file.take(MAXIMUM_METADATA_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() as u64 > MAXIMUM_METADATA_BYTES {
        return None;
    }
    let mut failure: FailureRecord = serde_json::from_slice(&bytes).ok()?;
    let exact_mtime_ms = f64::from_bits(failure.source_mtime_bits);
    if !exact_mtime_ms.is_finite() || exact_mtime_ms < 0.0 {
        return None;
    }
    failure.source_mtime_ms = exact_mtime_ms;
    if failure.schema_version != CACHE_RECORD_SCHEMA_VERSION
        || failure.algorithm_version != DERIVATIVE_ALGORITHM_VERSION
        || failure.photo_identity != identity.photo_identity
        || failure.target_long_edge != identity.target.long_edge()
        || failure.source != identity.source
        || failure.source_relative_path != identity.source_relative_path
        || failure.source_size != identity.source_size
        || failure.source_mtime_ms != identity.source_mtime_ms
        || failure.embedded_candidate_identity != identity.embedded_candidate_identity
        || failure.key != expected_key
        || derivative_cache_key(identity).ok().as_deref() != Some(failure.key.as_str())
    {
        return None;
    }
    Some(failure)
}

fn failure_record(
    identity: &DerivativeIdentity,
    key: &str,
    kind: DerivativeFailureKind,
) -> FailureRecord {
    FailureRecord {
        schema_version: CACHE_RECORD_SCHEMA_VERSION,
        algorithm_version: DERIVATIVE_ALGORITHM_VERSION.to_owned(),
        photo_identity: identity.photo_identity.clone(),
        target_long_edge: identity.target.long_edge(),
        key: key.to_owned(),
        source: identity.source,
        source_relative_path: identity.source_relative_path.clone(),
        source_size: identity.source_size,
        source_mtime_ms: identity.source_mtime_ms,
        source_mtime_bits: identity.source_mtime_ms.to_bits(),
        embedded_candidate_identity: identity.embedded_candidate_identity.clone(),
        kind: match kind {
            DerivativeFailureKind::Unsupported => PersistentFailureKind::Unsupported,
            DerivativeFailureKind::Malformed => PersistentFailureKind::Malformed,
            DerivativeFailureKind::ResourceLimit => PersistentFailureKind::ResourceLimit,
            _ => PersistentFailureKind::Malformed,
        },
    }
}

fn persist_failure(path: &Path, failure: FailureRecord) -> Result<(), CacheError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|_| CacheError::Io)?;
    }
    let bytes = serde_json::to_vec(&failure).map_err(|_| CacheError::Io)?;
    let temporary = path.with_extension(format!(
        "json.{}.{}.tmp",
        std::process::id(),
        NEXT_TEMPORARY.fetch_add(1, Ordering::Relaxed)
    ));
    write_new_file(&temporary, &bytes)?;
    let result = fs::rename(&temporary, path).map_err(|_| CacheError::Io);
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

fn remove_if_present(path: &Path) -> Result<(), CacheError> {
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(_) => Err(CacheError::Io),
    }
}

fn failure_for_error(error: DerivativeError) -> DerivativeFailure {
    DerivativeFailure {
        kind: match error {
            DerivativeError::Unsupported => DerivativeFailureKind::Unsupported,
            DerivativeError::Malformed => DerivativeFailureKind::Malformed,
            DerivativeError::ResourceLimit => DerivativeFailureKind::ResourceLimit,
            DerivativeError::OutputLimit => DerivativeFailureKind::ResourceLimit,
            DerivativeError::Internal => DerivativeFailureKind::Internal,
        },
    }
}

fn manifest_matches_identity(manifest: &Manifest, identity: &DerivativeIdentity) -> bool {
    manifest.schema_version == CACHE_RECORD_SCHEMA_VERSION
        && manifest.algorithm_version == DERIVATIVE_ALGORITHM_VERSION
        && manifest.photo_identity == identity.photo_identity
        && manifest.target_long_edge == identity.target.long_edge()
        && manifest.source == identity.source
        && manifest.source_relative_path == identity.source_relative_path
        && manifest.source_size == identity.source_size
        && manifest.source_mtime_ms == identity.source_mtime_ms
        && manifest.embedded_candidate_identity == identity.embedded_candidate_identity
        && derivative_cache_key(identity).ok().as_deref() == Some(manifest.key.as_str())
}

fn selected_original<'a>(
    photo: &PhotoRecord,
    originals: &'a [OriginalRecord],
) -> Option<(PreviewCandidate, &'a OriginalRecord)> {
    let find = |id: &Option<String>| {
        id.as_ref().and_then(|id| {
            originals.iter().find(|original| {
                &original.id == id && original.available && original.error_category.is_none()
            })
        })
    };
    find(&photo.jpeg_original_id)
        .filter(|original| original.kind == OriginalKind::Jpeg)
        .map(|original| (PreviewCandidate::MatchingJpeg, original))
        .or_else(|| {
            find(&photo.raw_original_id)
                .filter(|original| original.kind == OriginalKind::Raw)
                .map(|original| (PreviewCandidate::EmbeddedRawJpeg, original))
        })
}

fn manifest_is_for_photo_target(manifest: &Manifest, identity: &DerivativeIdentity) -> bool {
    manifest.schema_version == CACHE_RECORD_SCHEMA_VERSION
        && manifest.algorithm_version == DERIVATIVE_ALGORITHM_VERSION
        && manifest.photo_identity == identity.photo_identity
        && manifest.target_long_edge == identity.target.long_edge()
        && manifest_key_is_valid(manifest)
}

fn manifest_is_stale_for_identity(manifest: &Manifest, identity: &DerivativeIdentity) -> bool {
    manifest_is_for_photo_target(manifest, identity)
        && (manifest.source_relative_path != identity.source_relative_path
            || manifest.source_size != identity.source_size
            || manifest.source_mtime_ms != identity.source_mtime_ms
            || manifest.source != identity.source
            || manifest.embedded_candidate_identity != identity.embedded_candidate_identity)
}

fn manifest_key_is_valid(manifest: &Manifest) -> bool {
    let target = match manifest.target_long_edge {
        512 => DerivativeTarget::Thumbnail512,
        2560 => DerivativeTarget::Review2560,
        _ => return false,
    };
    let identity = DerivativeIdentity {
        photo_identity: manifest.photo_identity.clone(),
        source: manifest.source,
        source_relative_path: manifest.source_relative_path.clone(),
        source_size: manifest.source_size,
        source_mtime_ms: manifest.source_mtime_ms,
        embedded_candidate_identity: manifest.embedded_candidate_identity.clone(),
        target,
    };
    derivative_cache_key(&identity).ok().as_deref() == Some(manifest.key.as_str())
}

fn cached_from_manifest(
    cache: &CacheDirectory,
    manifest: &Manifest,
    facts: ManifestFacts,
    generated: bool,
) -> CachedDerivative {
    CachedDerivative {
        cache_path: cache.derivative_path(&manifest.key),
        cache_key: manifest.key.clone(),
        source: manifest.source,
        source_relative_path: manifest.source_relative_path.clone(),
        source_size: manifest.source_size,
        source_mtime_ms: manifest.source_mtime_ms,
        embedded_candidate_identity: manifest.embedded_candidate_identity.clone(),
        width: facts.width,
        height: facts.height,
        profile: manifest.color_profile.into(),
        generated,
        stale: false,
    }
}

pub fn derivative_cache_key(identity: &DerivativeIdentity) -> Result<String, CacheError> {
    identity.validate()?;
    #[derive(Serialize)]
    struct Key<'a> {
        version: &'static str,
        photo: &'a str,
        source: DerivativeSource,
        path: &'a str,
        size: u64,
        #[serde(rename = "mtimeMs")]
        mtime_ms: f64,
        candidate: Option<&'a str>,
        edge: u32,
    }
    let key = Key {
        version: DERIVATIVE_ALGORITHM_VERSION,
        photo: &identity.photo_identity,
        source: identity.source,
        path: &identity.source_relative_path,
        size: identity.source_size,
        mtime_ms: identity.source_mtime_ms,
        candidate: identity.embedded_candidate_identity.as_deref(),
        edge: identity.target.long_edge(),
    };
    Ok(hex_digest(
        &serde_json::to_vec(&key).map_err(|_| CacheError::InvalidIdentity)?,
    ))
}

fn manifest_identity_for_photo_target(
    photo_id: &str,
    target: DerivativeTarget,
) -> Result<String, CacheError> {
    if photo_id.is_empty() || photo_id.contains('\0') {
        return Err(CacheError::InvalidIdentity);
    }
    #[derive(Serialize)]
    struct Key<'a> {
        photo: &'a str,
        edge: u32,
    }
    let key = Key {
        photo: photo_id,
        edge: target.long_edge(),
    };
    Ok(hex_digest(
        &serde_json::to_vec(&key).map_err(|_| CacheError::InvalidIdentity)?,
    ))
}

pub fn manifest_identity(identity: &DerivativeIdentity) -> Result<String, CacheError> {
    identity.validate()?;
    manifest_identity_for_photo_target(&identity.photo_identity, identity.target)
}

fn hex_digest(bytes: &[u8]) -> String {
    let mut digest = Sha256::new();
    digest.update(bytes);
    format!("{:x}", digest.finalize())
}

fn is_hex_key(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
}

fn reject_cache_under_original(
    cache_directory: &Path,
    canonical_original_root: &Path,
) -> Result<(), CacheError> {
    let lexical_cache = lexical_absolute_path(cache_directory)?;
    if lexical_cache == canonical_original_root
        || lexical_cache.starts_with(canonical_original_root)
    {
        return Err(CacheError::InvalidCacheDirectory);
    }
    let mut existing = cache_directory;
    while !existing.exists() {
        existing = existing.parent().ok_or(CacheError::InvalidCacheDirectory)?;
    }
    let canonical_existing =
        fs::canonicalize(existing).map_err(|_| CacheError::InvalidCacheDirectory)?;
    if canonical_existing == canonical_original_root
        || canonical_existing.starts_with(canonical_original_root)
    {
        return Err(CacheError::InvalidCacheDirectory);
    }
    Ok(())
}

fn lexical_absolute_path(path: &Path) -> Result<PathBuf, CacheError> {
    let mut result = PathBuf::new();
    for component in path.components() {
        match component {
            Component::RootDir => result.push(component.as_os_str()),
            Component::Normal(value) => result.push(value),
            Component::CurDir => {}
            Component::ParentDir => {
                result.pop();
            }
            Component::Prefix(_) => return Err(CacheError::InvalidCacheDirectory),
        }
    }
    Ok(result)
}

fn is_safe_relative_utf8_path(value: &str) -> bool {
    let path = Path::new(value);
    if value.is_empty() || path.is_absolute() {
        return false;
    }
    path.components()
        .all(|component| matches!(component, Component::Normal(_)))
}

#[cfg(unix)]
const fn no_follow_flag() -> i32 {
    libc::O_NOFOLLOW | libc::O_CLOEXEC
}

#[cfg(not(unix))]
const fn no_follow_flag() -> i32 {
    0
}

